15	export function getCommonAttributes(config: Config): Attributes {
16	  const email = userAccountManager.getCachedGoogleAccount();
17	  const experiments = config.getExperiments();
18	  const authType = config.getContentGeneratorConfig()?.authType;
19	  return {
20	    'session.id': config.getSessionId(),
21	    'installation.id': installationManager.getInstallationId(),
22	    interactive: config.isInteractive(),
23	    ...(email && { 'user.email': email }),
24	    ...(authType && { auth_type: authType }),
25	    ...(experiments &&
26	      experiments.experimentIds.length > 0 && {
27	        'experiments.ids': experiments.experimentIds,
28	      }),
29	  };
30	}
